  [CB 8 j0; C8 c8; C8 c24; C8 c32; C8 (Z_to_bv 64 (DCTX + 26688)); C8 c88; C8 c120;
   C8 (Z_to_bv 64 (DCTX + 26692)); C8 (Z_to_bv 64 (DCTX + 26684)); C8 (Z_to_bv 64 (2147450880 + D8 + 3336)); C8 (Z_to_bv 64 (2147450880 + D8 + 3336)); C8 (Z_to_bv 64 (2147450880 + D8 + 3335));
   C8 c16; C8 (Z_to_bv 64 (Z.min nbSeq 8)); C8 c160; C8 dend; C8 (Z_to_bv 64 PFX); C8 c224; C8 (Z_to_bv 64 SHF);
   C8 (Z_to_bv 64 (2147450880 + D8 + 3795)); C8 (Z_to_bv 64 (DCTX + 30360)); C8 (Z_to_bv 64 OEND); C8 (Z_to_bv 64 nbSeq); C8 (Z_to_bv 64 (DCTX + 30368)); C8 (Z_to_bv 64 DCTX);
   C8 (Z_to_bv 64 FF); C8 c248; C8 c264; C8 (Z_to_bv 64 PFX); C8 (Z_to_bv 64 DST); C8 c304; C8 (Z_to_bv 64 FF); C8 (Z_to_bv 64 (FF + 120)); C8 (Z_to_bv 64 (2147450880 + D8 + 3796));
   C8 c312; C8 c368; C8 c328; C8 c336; C8 c96; C8 c376; CB 24 j384;
   CB 192 (sql_ring_bytes rl rm ro); C8 (Z_to_bv 64 LP); CB 24 jseq].

