(* [comment removed for export] *)
Definition sql_linv (P : slq) (OEND LLO LEND LOCV : Z) (m1 : amem)
                    (c8 c16 c24 c32 c88 c96 c120 c128 c160 c224 c232 c248 c264 c304 c312 c320 c328 c336 c352 c368 c376 cw : word) (bc ptr sLL sOF sML : Z) (p0 p1 p2 : word)
                    (rl rm ro : Z -> Z) (LP : Z) : Prop :=
  (exists jpad jseq, rw_cells bsegs m1 (l_FRB P) (sql_frame P OEND c8 c16 c24 c32 c88 c96 c120 c128 c160 c224 c232 c248 c264 c304 c312 c320 c328 c336 c352 c368 c376 rl rm ro LP jseq) /\
                     rw_cells bsegs m1 (l_FF P) (sql_ffr P cw bc ptr sLL sOF sML p0 p1 p2 jpad)) /\
  bytes_at bsegs m1 (l_LLT P) (map (Z_to_bv 8) (seq_table_bytes (l_tLL P))) /\
  bytes_at bsegs m1 (l_OFT P) (map (Z_to_bv 8) (seq_table_bytes (l_tOF P))) /\
  bytes_at bsegs m1 (l_MLT P) (map (Z_to_bv 8) (seq_table_bytes (l_tML P))) /\
  bytes_at bsegs m1 (l_SEQ P) (map (Z_to_bv 8) (l_sq P)) /\
  rdbl bsegs m1 LLO (LEND + 32) /\
  (LOCV = 2 -> rdbl bsegs m1 (l_DCTX P + 30372) (l_DCTX P + 95940)) /\
  h5_viewed m1 (l_DCTX P) (l_ws P) (Z_to_bv 64 LOCV) /\
  sql_xinv P m1 (sql_fe P).

(* [comment removed for export] *)
Definition sql_lfacts (P : slq) (OEND LLO LEND BND OP LP bc ptr sLL sOF sML : Z) : Prop :=
  l_DST P <= OP <= OEND /\ LLO <= LP <= LEND /\
  0 <= sLL < 2^(st_log (l_tLL P)) /\ 0 <= sOF < 2^(st_log (l_tOF P)) /\ 0 <= sML < 2^(st_log (l_tML P)) /\
  0 <= bc <= BND /\ bit_ok (l_SEQ P) (zlen (l_sq P)) bc ptr.

(* [comment removed for export] *)
Definition sql_next (P : slq) (nLL bLL nOF bOF nML bML : Z) : Prop :=
  0 <= bLL <= 9 /\ 0 <= nLL /\ nLL + 2^bLL <= 2^(st_log (l_tLL P)) /\
  0 <= bOF <= 9 /\ 0 <= nOF /\ nOF + 2^bOF <= 2^(st_log (l_tOF P)) /\
  0 <= bML <= 9 /\ 0 <= nML /\ nML + 2^bML <= 2^(st_log (l_tML P)).

(* [comment removed for export] *)
Definition sql_fast (OEND LEND OP LP llv mlv : Z) : Prop :=
  0 <= llv < 2^18 /\ 0 <= mlv < 2^18 /\ LP + llv <= LEND /\ OP + llv + mlv <= OEND - 32.

(* [comment removed for export] *)
Definition sql_mfast (P : slq) (OEND OP ole mlv sl : Z) : Prop :=
  l_DST P <= OP <= ole /\ 0 <= mlv < 2^18 /\ ole + mlv <= OEND - 32 /\ sl = ole - OP + mlv.

